const clamp = (n, a, b) => Math.min(b, Math.max(a, n));

export const SAFE = 0.08;

export function readableOn(color) {
  const hex = String(color || '').trim().replace('#', '');
  const full = hex.length === 3 ? hex.split('').map((c) => c + c).join('') : hex;
  const value = /^[0-9a-fA-F]{6}$/.test(full.slice(0, 6)) ? parseInt(full.slice(0, 6), 16) : null;
  if (value == null) return '#0a0a0a';
  const r = (value >> 16) & 255, g = (value >> 8) & 255, b = value & 255;
  const lum = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
  return lum > 0.55 ? '#0a0a0a' : '#fdfaf3';
}

export function setFont(ctx, fs, style, token) {
  const name = token?.font || style.font || 'Inter';
  const safe = String(name).replace(/["']/g, '');
  const family = safe.includes(' ') ? `"${safe}"` : safe;
  const italic = token?.italic || style.italic;
  const weight = token?.weight || style.weight || 800;
  ctx.font = `${italic ? 'italic ' : ''}${weight} ${Math.max(1, fs)}px ${family}, Inter, Arial, sans-serif`;
}

export function measure(ctx, text, fs, style, token) {
  setFont(ctx, fs, style, token);
  return ctx.measureText(text).width;
}

export function baseFont(style, W, H) {
  const size = Number(style.size) || 5.2;
  const short = Math.min(W, H);
  const fromH = (size / 100) * H;
  const fromShort = (size / 100) * short * (W < H ? 1.02 : 1.28);
  let fs = Math.min(fromH, fromShort);
  if (H < 240) fs = Math.max(fs, H * 0.145);
  return fs;
}

export function tokenBox(t) {
  const s = (t.scale || 1) * (t.scaleMul || 1);
  return {
    l: t.x - (t.w * s) / 2,
    r: t.x + (t.w * s) / 2,
    t: t.y - t.h * s * 0.82,
    b: t.y + t.h * s * 0.22,
  };
}

export function groupBounds(tokens) {
  if (!tokens.length) return { l: 0, r: 0, t: 0, b: 0, cx: 0, cy: 0, w: 0, h: 0 };
  let l = Infinity, r = -Infinity, t = Infinity, b = -Infinity;
  for (const tok of tokens) {
    const box = tokenBox(tok);
    l = Math.min(l, box.l); r = Math.max(r, box.r);
    t = Math.min(t, box.t); b = Math.max(b, box.b);
  }
  return { l, r, t, b, cx: (l + r) / 2, cy: (t + b) / 2, w: r - l, h: b - t };
}

export function fitSafe(tokens, W, H, margin = SAFE, maxBand = 1) {
  if (!tokens.length) return tokens;
  const maxW = W * Math.min(1 - margin * 2, maxBand);
  const maxH = H * Math.min(1 - margin * 2, maxBand);
  const g = groupBounds(tokens);
  const s = Math.min(1, maxW / Math.max(8, g.w), maxH / Math.max(8, g.h));
  if (s < 0.995) {
    for (const tok of tokens) {
      tok.x = g.cx + (tok.x - g.cx) * s;
      tok.y = g.cy + (tok.y - g.cy) * s;
      tok.fs *= s;
      tok.w *= s;
      tok.h *= s;
    }
  }
  const g2 = groupBounds(tokens);
  let dx = 0, dy = 0;
  if (g2.l < W * margin) dx = W * margin - g2.l;
  if (g2.r > W * (1 - margin)) dx = W * (1 - margin) - g2.r;
  if (g2.t < H * margin) dy = H * margin - g2.t;
  if (g2.b > H * (1 - margin)) dy = H * (1 - margin) - g2.b;
  if (dx || dy) for (const tok of tokens) { tok.x += dx; tok.y += dy; }
  return tokens;
}

export function placeLinesWith(ctx, lines, sizes, roles, style, kind, ax, ay, tracking = 0.08, spacingFrac = 0, display = (text) => String(text)) {
  const measured = lines.map((line, li) => line.map((w, wi) => {
    const role = roles[li][wi];
    const fs = sizes[li][wi];
    const raw = w.text;
    const face = { font: w.font || (role === 'hero' ? style.highlightFont : null), italic: w.italic };
    const text = display(w.text, role, kind, style);
    // Letter-spaced styles draw wider than the bare glyph run; reserve it here
    // so neighbouring words never collide.
    const width = measure(ctx, text, fs, style, face) + (spacingFrac ? fs * spacingFrac * Math.max(0, Array.from(text).length - 1) : 0);
    return { ...w, raw, text, fs, width, role, font: face.font, italic: face.italic };
  }));
  const lineH = measured.map((line) => Math.max(...line.map((w) => w.fs)) * 0.90);
  const gapY = (lineH[0] || 16) * 0.12;
  const totalH = lineH.reduce((s, h) => s + h, 0) + gapY * Math.max(0, lineH.length - 1);
  let y = ay - totalH / 2;
  const tokens = [];
  measured.forEach((line, li) => {
    const spaces = line.map((w) => measure(ctx, ' ', w.fs, style) * (0.52 + tracking));
    let width = 0;
    line.forEach((w, i) => { width += w.width + (i ? spaces[i] : 0); });
    let x = ax - width / 2;
    line.forEach((w, i) => {
      if (i) x += spaces[i];
      tokens.push({
        id: w.id,
        text: w.text,
        raw: w.raw || w.text,
        start: w.start,
        end: w.end,
        x: x + w.width / 2,
        y: y + lineH[li] * 0.84,
        w: w.width,
        h: w.fs,
        fs: w.fs,
        scale: 1,
        rot: 0,
        role: w.role,
        opacity: 1,
        line: li,
        font: w.font,
        italic: w.italic,
      });
      x += w.width;
    });
    y += lineH[li] + gapY;
  });
  return tokens;
}
